def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result") if isinstance(resp, dict) else None
    if not isinstance(result, dict):
        return {"action": "queue_review", "limit": 0}

    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit") or 0

    if outcome == "approved":
        action = "issue"
        limit = int(credit_limit)
    elif outcome == "declined":
        action = "decline"
        limit = 0
    elif outcome == "manual_review":
        action = "queue_review"
        limit = 0
    else:
        return {"action": "queue_review", "limit": 0}

    # Network referral rule: self-employed applicant with requested_limit > 6000
    # must go to manual review instead of being issued (a decline stays a decline).
    if (action == "issue"
            and app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 6000):
        return {"action": "queue_review", "limit": 0}

    return {"action": action, "limit": limit}

